// The commit rules in the repository's root instructions file, as code: no commit credits an AI tool as author,
// committer or in its message.
//
// Two rules, split at BASELINE, the last commit the old one judged:
//  - Up to and including BASELINE, the old rule: a co-author, sign-off, reviewer or assistant trailer, or a line
//    saying the commit was generated by a tool, that names a tool. The history holds trailers of another shape
//    (session ids) that the old rule never saw; those commits are an accepted exception and must not turn CI red.
//  - After BASELINE, the strict rule: any line at all, trailer-shaped or free, that names one of the tools or
//    vendors below, as well as everything the old rule refuses. The one exception is the first line git writes by
//    itself for a merge or a revert, which is not held to the free-line part (a branch called after a tool is not a
//    credit); a credit-shaped line is refused there too.
//
// The names are written in pieces on purpose: the repository is scanned for them, and the rule that looks for them
// must not be what the scan finds.

const word = (...parts) => parts.join("");

// Both are written in full: an abbreviation can turn ambiguous as the history grows. If the history is ever rewritten
// again, these two must be set to the new commits, and a fetch will not fix a check that cannot find them.

/** The last commit of the history judged by the old rule: v0.20.3. */
export const BASELINE = "756d15b73e087f8962c793c0fa1c5b579730adaa";
/** The last upstream Helicon commit; everything after it is Ancilla's. */
export const FORK_POINT = "8e5b141f4285364e30011897cae74ed9adb29683";

// The old rule, unchanged.
const LEGACY_TOOLS = new RegExp([word("cla", "ude"), word("anthr", "opic"), word("copi", "lot"), word("co", "dex"), word("open", "ai"), "gemini", "cursor"].join("|"), "i");
const LEGACY_TRAILER = new RegExp(`^(${[word("co-auth", "ored-by"), "signed-off-by", "reviewed-by", "assisted-by"].join("|")}):`, "i");
const LEGACY_GENERATED = new RegExp(`${word("gener", "ated")} (with|by)[^a-z]*(${[word("cla", "ude"), word("copi", "lot"), word("co", "dex"), "gpt", "gemini", "cursor"].join("|")})`, "i");

// The strict rule: whole names, so that a longer word or a surname does not match. Gemini and cursor are left out
// on purpose, since both are ordinary words; the old rule still covers them in a credit line.
const STRICT_NAMES = new RegExp(
  `(?<![a-z0-9])(?:${[word("cla", "ude"), word("anthr", "opic"), word("copi", "lot"), word("co", "dex"), word("chat", "gpt"), word("open", "ai"), "gpt"].join("|")})(?![a-z])`,
  "i",
);

// The first line git composes by itself for a merge or a revert. It quotes a branch, a pull request's head or the
// reverted subject, so it can carry a tool's name nobody typed (a branch called after one). Only that first line, and
// only from the strict free-line rule: a credit-shaped line is a credit wherever it stands.
const GIT_FIRST_LINE = /^(?:Merge (?:branch|pull request|remote-tracking branch)|Revert ")/;

// The line git writes between a message and the diff that `git commit -v` (or commit.verbose, or --cleanup=scissors)
// appends to the file: a comment character, 24 dashes, ">8", 24 dashes. Everything under it is git's, not the message.
const SCISSORS = /^.{1} -{24} >8 -{24}$/;

/**
 * The lines of a message that credit a tool, trimmed, each once.
 *
 * `editorText` is for the file git hands the commit-msg hook, which still holds what git wrote for the editor: the
 * status lines it comments out, and under `commit -v` the whole diff under a scissors line. None of that is the message,
 * so the scissors line ends it and a `#` line is not held to the strict rule (a branch or file name in it, in any
 * language git was installed in, is not a credit). It is still held to the old one, since `git commit -m` keeps a `#`
 * line in the message, and a credit is a credit with a `#` in front of it.
 */
export function messageProblems(body, { strict = false, editorText = false } = {}) {
  const problems = [];
  let first = true;
  for (const raw of String(body).split(/\r?\n/)) {
    if (editorText && SCISSORS.test(raw)) break;
    const comment = editorText && raw.startsWith("#");
    const line = (comment ? raw.slice(1) : raw).trim();
    if (line === "") continue;
    // The first line of the message proper, which git may have written itself (a merge or a revert).
    const gitWritten = first && !comment && GIT_FIRST_LINE.test(line);
    if (!comment) first = false;
    const old = (LEGACY_TRAILER.test(line) && LEGACY_TOOLS.test(line)) || LEGACY_GENERATED.test(line);
    if (old || (strict && !comment && !gitWritten && STRICT_NAMES.test(line))) problems.push(raw.trim());
  }
  return problems;
}

/** Whether an author or committer, as "Name <email>", is an AI tool. Applies to every commit. */
export function identityProblems(identity) {
  return LEGACY_TOOLS.test(identity) ? [identity] : [];
}

/**
 * Walks `range` and lists what is wrong, with the strict rule for the commits that are not part of BASELINE's history.
 * `git(args)` runs git and returns its standard output.
 * @returns {string[]} one line per problem, each starting with the commit's short hash
 */
export function rangeProblems({ git, range, baseline = BASELINE }) {
  try {
    git(["rev-parse", "--verify", "--quiet", `${baseline}^{commit}`]);
  } catch {
    throw new Error(`The baseline ${baseline} is not in this history: fetch all of it (CI checks out with fetch-depth: 0), or, if the history was rewritten, pin BASELINE and FORK_POINT in scripts/lib/attribution.mjs to the new commits`);
  }
  const strictHashes = new Set(git(["rev-list", range, `^${baseline}`]).split("\n").filter(Boolean));
  const log = git(["log", "--format=%H%x1f%an <%ae>%x1f%cn <%ce>%x1f%B%x1e", range]);
  const problems = [];
  for (const record of log.split("\x1e")) {
    if (!record.trim()) continue;
    const [hash, author, committer, body] = record.replace(/^\n/, "").split("\x1f");
    const short = hash.slice(0, 7);
    if (identityProblems(author).length > 0) problems.push(`${short}: author is ${author}`);
    if (identityProblems(committer).length > 0) problems.push(`${short}: committer is ${committer}`);
    for (const line of messageProblems(body, { strict: strictHashes.has(hash) })) {
      problems.push(`${short}: message says "${line}"`);
    }
  }
  return problems;
}
